exercises.solution:
def conv2d(image, kernel):
    H, W = len(image), len(image[0])
    h, w = len(kernel), len(kernel[0])
    return [[sum(image[i + a][j + b] * kernel[a][b] for a in range(h) for b in range(w))
             for j in range(W - w + 1)]
            for i in range(H - h + 1)]

